import { useNotifications } from '@/app/providers/NotificationProvider'
import { NotificationItem } from '@/shared/ui/NotificationItem'
import { Bell } from 'lucide-react'

export function InboxPanel() {
  const { notifications, markRead } = useNotifications()

  return (
    <div className="flex flex-col h-full overflow-y-auto">
      <div className="p-3 border-b border-border flex items-center justify-between">
        <span className="text-xs text-muted-foreground font-medium uppercase tracking-wide">Inbox</span>
        <span className="text-xs text-muted-foreground">{notifications.filter((n) => !n.read).length} unread</span>
      </div>
      {notifications.length === 0 ? (
        <div className="flex flex-col items-center justify-center flex-1 gap-2 text-muted-foreground py-8">
          <Bell size={24} />
          <p className="text-sm">No notifications</p>
        </div>
      ) : (
        <div className="flex flex-col">
          {notifications.map((n) => (
            <NotificationItem key={n.id} notification={n} onRead={markRead} />
          ))}
        </div>
      )}
    </div>
  )
}
